package org.humanjourney.core.integration.xaero.client;
import java.util.*;
import net.minecraft.client.gui.components.*;
import net.minecraft.network.chat.Component;
import net.minecraftforge.client.event.ScreenEvent;
import xaero.map.gui.GuiMap;
import org.humanjourney.core.geography.client.GeographyClientConfig;
import org.humanjourney.core.geography.map.client.*;
import org.humanjourney.core.integration.xaero.XaeroStatus;
import org.humanjourney.core.mapfeature.client.FeatureClient;
/** Optional exact-version client UI; public Forge screen hooks, no additional Xaero Mixin. */
public final class XaeroBoundaryControl {
 private static final class Entry{Button button,featureButton;boolean failed;String problem="",featureProblem="";final BoundaryControlInput input=new BoundaryControlInput();}
 private static final Map<GuiMap,Entry> controls=new WeakHashMap<>();
 public static void register(){
  ScreenEvent.Init.Post.BUS.addListener(event->{if(event.getScreen() instanceof GuiMap screen){var entry=new Entry();controls.put(screen,entry);try{entry.button=Button.builder(Component.literal(GeographyClientConfig.mode().label()),b->cycle(entry)).bounds(8,8,BoundaryControlLayout.WIDTH,BoundaryControlLayout.HEIGHT).build();entry.button.visible=false;event.addListener(entry.button);entry.featureButton=Button.builder(Component.literal(GeographyClientConfig.featureMode().label()),b->cycleFeature(entry)).bounds(8,32,BoundaryControlLayout.WIDTH,BoundaryControlLayout.HEIGHT).build();entry.featureButton.visible=false;event.addListener(entry.featureButton);update(screen,entry);}catch(RuntimeException|ReflectiveOperationException|LinkageError error){fail(entry,error);}}});
  ScreenEvent.Render.Pre.BUS.addListener(event->{if(event.getScreen() instanceof GuiMap screen){var entry=controls.get(screen);if(entry!=null&&!entry.failed)try{update(screen,entry);}catch(RuntimeException|ReflectiveOperationException|LinkageError error){fail(entry,error);}}});
  ScreenEvent.Render.Post.BUS.addListener(event->{if(event.getScreen() instanceof GuiMap screen){var entry=controls.get(screen);if(entry!=null&&!entry.failed)try{for(var button:new Button[]{entry.button,entry.featureButton})if(button!=null&&button.visible)button.render(event.getGuiGraphics(),event.getMouseX(),event.getMouseY(),event.getPartialTick());}catch(RuntimeException|LinkageError error){fail(entry,error);}}});
  ScreenEvent.MouseButtonPressed.Pre.BUS.addListener((java.util.function.Predicate<ScreenEvent.MouseButtonPressed.Pre>)event->{if(event.getScreen() instanceof GuiMap screen){var entry=controls.get(screen);if(entry==null)return false;for(var b:new Button[]{entry.button,entry.featureButton}){if(b==null)continue;var bounds=new BoundaryControlLayout.Rect(b.getX(),b.getY(),b.getWidth(),b.getHeight());var action=entry.input.press(bounds,!entry.failed&&b.visible&&b.active,event.getMouseX(),event.getMouseY(),event.getButton());if(action!=BoundaryControlInput.Action.PASS){try{if(action==BoundaryControlInput.Action.CYCLE)b.mouseClicked(event.getMouseX(),event.getMouseY(),0);}catch(RuntimeException|LinkageError error){fail(entry,error);}return true;}}}return false;});
  ScreenEvent.MouseButtonReleased.Pre.BUS.addListener((java.util.function.Predicate<ScreenEvent.MouseButtonReleased.Pre>)event->{if(event.getScreen() instanceof GuiMap screen){var entry=controls.get(screen);return entry!=null&&entry.input.release(event.getButton());}return false;});
  ScreenEvent.MouseDragged.Pre.BUS.addListener((java.util.function.Predicate<ScreenEvent.MouseDragged.Pre>)event->{if(event.getScreen() instanceof GuiMap screen){var entry=controls.get(screen);return entry!=null&&entry.input.drag(event.getMouseButton());}return false;});
 }
 private static void cycle(Entry entry){try{GeographyClientConfig.mode(GeographyClientConfig.mode().next());entry.problem="";entry.button.setMessage(Component.literal(GeographyClientConfig.mode().label()));}catch(RuntimeException error){entry.problem="Could not save boundary mode; previous preference retained: "+error.getClass().getSimpleName();XaeroStatus.control(entry.problem);com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] {}",entry.problem,error);}}
 private static void cycleFeature(Entry entry){try{GeographyClientConfig.featureMode(GeographyClientConfig.featureMode().next());entry.featureProblem="";entry.featureButton.setMessage(Component.literal(GeographyClientConfig.featureMode().label()));}catch(RuntimeException error){entry.featureProblem="Could not save feature mode; previous preference retained: "+error.getClass().getSimpleName();FeatureClient.control(entry.featureProblem);com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] {}",entry.featureProblem,error);}}
 private static void hidden(String reason){XaeroStatus.control(reason);FeatureClient.control(reason);}
 private static void update(GuiMap screen,Entry entry)throws IllegalAccessException{entry.button.setMessage(Component.literal(GeographyClientConfig.mode().label()));entry.featureButton.setMessage(Component.literal(GeographyClientConfig.featureMode().label()));for(var b:new Button[]{entry.button,entry.featureButton}){b.visible=false;b.active=false;}if(!Xaero13913Adapter.controlsUsable(screen)||Xaero13913Adapter.controlMenusOpen(screen)){hidden("Hidden while map presentation is unavailable or a native menu is open");return;}var occupied=new ArrayList<BoundaryControlLayout.Rect>();for(var child:screen.children())if(child instanceof AbstractWidget widget&&widget!=entry.button&&widget!=entry.featureButton&&widget.visible)occupied.add(new BoundaryControlLayout.Rect(widget.getX(),widget.getY(),widget.getWidth(),widget.getHeight()));var place=BoundaryControlLayout.placePair(screen.width,screen.height,occupied);if(place.isEmpty()){hidden("No collision-free map-control space outside compass; config preferences remain usable");return;}var p=place.get();var buttons=new Button[]{entry.button,entry.featureButton};for(int i=0;i<2;i++){var b=buttons[i];b.setX(p.get(i).x());b.setY(p.get(i).y());b.visible=i==0?GeographyClientConfig.MAP_ENABLED.get():GeographyClientConfig.FEATURES_ENABLED.get();b.active=b.visible;}XaeroStatus.control(!entry.button.visible?"Disabled in client config":entry.problem.isEmpty()?"Ready at "+p.get(0).x()+","+p.get(0).y():entry.problem);FeatureClient.control(!entry.featureButton.visible?"Disabled in client config":entry.featureProblem.isEmpty()?"Ready at "+p.get(1).x()+","+p.get(1).y():entry.featureProblem);}
 private static void fail(Entry entry,Throwable error){entry.failed=true;for(var b:new Button[]{entry.button,entry.featureButton})if(b!=null){b.visible=false;b.active=false;}entry.problem="Map control unavailable; config-based boundaries remain usable: "+error.getClass().getSimpleName();hidden(entry.problem);com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] {}",entry.problem,error);}
 private XaeroBoundaryControl(){}
}
